 \label{incoherence}
Let $\mathcal{T} \in \mathbb{K}^{n_1\times n_2\times n_3}$ 
 be a tubal-rank $r$ tensor with a compact t-SVD $\mathcal{T}=\mathcal{W}*\mathcal{S}*\mathcal{V}^{\top}$. Then  $\mathcal{T}$ has $\mu_0$-incoherence  if  for all $ k\in\{1\cdots,n_3\}$, the following  hold:
\begin{equation*}
\max _{i=1,2, ., n_1}\left\|[\widehat{\mathcal{W}}]_{:,:,k}^{\top} \cdot \mathbf{e}_i\right\|_{{\mathrm{F}}} \leq \sqrt{\frac{\mu_0 r}{n_1 }} \quad 
 \text{ and } \quad 
\max _{j=1,2, \ldots, n_2}\left\|[\widehat{\mathcal{V}}]_{:,:,k}^{\top}\cdot \mathbf{e}_j\right\|_{{\mathrm{F}}} \leq \sqrt{\frac{\mu_0 r}{n_2 }}.
\end{equation*}
In some cases, to highlight the incoherence parameter of a specific tensor $\mathcal{T}$, we will denote this parameter as $\mu_{\mathcal{T}}$.

\rm
The tensor nuclear norm (\textnormal{TNN}) of $\mathcal{T}$ is defined as 

 $\left\|\mathcal{T}\right\|_{\textnormal{TNN}} 
 = \frac{1}{n_3}\left\|\operatorname{bcirc}{(\mathcal{T})}\right\|_{*}
 = \frac{1}{n_3}\left\|\overline{\mathcal{T}}\right\|_{*}$, 

 where $\left\|\cdot\right\|_{*}$ is the matrix nuclear norm.

\caption{Tensor Cross-Concentrated Sampling (t-CCS)}\label{prod:t-CCS}
\begin{algorithmic}[1]
\State \textbf{Input:}  $\mathcal{T}\in \mathbb{K}^{n_1 \times n_2 \times n_3}$.
\State  Uniformly select the horizontal and lateral indices, denoted as \(I\) and \(J\), respectively.
\State Set $\mathcal{R}:=[\mathcal{T}]_{I,:,:}$ and $\mathcal{C}:=[\mathcal{T}]_{:,J,:}$.
\State Sample entries from \(\mathcal{R}\) and \(\mathcal{C}\) based on Bernoulli sampling models. Record the locations of these samples as \(\Omega_{\mathcal{R}}\) and \(\Omega_{\mathcal{C}}\) for \(\mathcal{R}\) and \(\mathcal{C}\), respectively.
\State\textbf{Output:} 
$[\mathcal{T}]_{\Omega_{\mathcal{R}}\cup \Omega_{\mathcal{C}}}$,
$\Omega_{\mathcal{R}}$, $\Omega_{\mathcal{C}}$, $I$, $J$.
\end{algorithmic}

\label{thm:samplingcmp4ccs} 
Let $\mathcal{T} \in \mathbb{K}^{n_1 \times n_2 \times n_3}$  satisfy the tensor $\mu_0$-incoherence condition  and have a multi-rank $\vec{r}$ with condition number $\kappa$. Let $I\subseteq [n_1]$ and $J \subseteq[n_2]$ be chosen uniformly with replacement to yield $\mathcal{R}=[\mathcal{T}]_{I,:,:}$ and $\mathcal{C}=[\mathcal{T}]_{:,J,:}$. And suppose that $\Omega_{\mathcal{R}}$ and $\Omega_{\mathcal{C}}$ are generated from $\mathcal{R}$ and $\mathcal{C}$  according to the Bernoulli distributions  with probability $p_{\mathcal{R}}$ and $p_{\mathcal{C}}$,  respectively.   If
\begin{align*}
|I|\geq  3200\beta\mu_0r\kappa^2\log^2(n_1n_3+n_2n_3),~&~
|J|\geq  3200\beta\mu_0r\kappa^2\log^2(n_1n_3+n_2n_3),\\
p_{\mathcal{R}} \geq \frac{1600(|I|+n_2)\mu_0r\kappa^2 \log^2((n_1+n_2)n_3) }{|I|n_2},~&~
p_{\mathcal{C}} \geq \frac{1600(|J|+n_1)\mu_0r\kappa^2 \log^2((n_1+n_2)n_3) }{|J|n_1}\,
\end{align*}
for some absolute constant $\beta>1$, 
then $\mathcal{T}$ can be uniquely determined from the entries on $\Omega_{\mathcal{R}}\cup \Omega_{\mathcal{C}}$ with probability at least
\begin{align*}
   1&-\frac{1}{(n_1n_3+n_2n_3)^{800\beta\kappa^2\log(n_2)}}-\frac{1}{(n_1n_3+n_2n_3)^{800\beta\kappa^2\log(n_1)}}\\
   &-\frac{3\log(n_1n_3+|J|n_3)}{(n_1n_3+|J|n_3)^{4\beta-2}}-\frac{3\log(n_2n_3+|I|n_3)}{(n_2n_3+|I|n_3)^{4\beta-2}}.
\end{align*}

\label{thm:sr4generalTCB}\rm
Let $\mathcal{Z}\in\mathbb{K}^{n_1 \times n_2 \times n_3}$ of tubal-rank $r$ satisfy the tensor $\mu_0$-incoherence condition. And its compact t-SVD is  $\mathcal{Z}=\mathcal{W} * \mathcal{S} * \mathcal{V}^{\top}$ where $\mathcal{W} \in \mathbb{K}^{n_1 \times r \times n_3}, \mathcal{S} \in \mathbb{K}^{r \times r \times n_3}$ and $\mathcal{V} \in \mathbb{K}^{n_2 \times r \times n_3}$. Suppose the entries in $\Omega$ are sampled according to the Bernoulli model with probability $p$.  If
\begin{equation}\label{ppp}
p \geq \frac{256\beta(n_1+n_2)\mu_0r\log^2(n_1n_3+n_2n_3)}{n_1n_2} \text{~with~}\beta\geq 1,
\end{equation}
then $\mathcal{Z}$ is the unique minimizer to 

\begin{equation*}
\begin{gathered}
\min _{\mathcal{X}}\|\mathcal{X}\|_{\textnormal{TNN}}, ~
\textnormal{ subject to } \mathcal{P}_{\Omega}(\mathcal{X})=\mathcal{P}_{\Omega}(\mathcal{Z}),
\end{gathered}
\end{equation*}
 with probability at least $1- \frac{3\log(n_1n_3+n_2n_3)}{(n_1n_3+n_2n_3)^{4\beta-2}}$.

\caption{Iterative t-CUR Tensor Completion (ITCURTC) for t-CCS }\label{ticur}
\begin{algorithmic}[1]
\State \textbf{Input:} 
$[\mathcal{T}]_{\Omega_{\mathcal{R}}\cup \Omega_{\mathcal{C}}}:$ observed data;
$\Omega_\mathcal{R}$, $\Omega_\mathcal{C}:$ observed locations; $I$, $J:$ horizontal and lateral indexes that define $\mathcal{R}$ and $\mathcal{C}$ respectively; $\eta_{R}, \eta_{C}, \eta_{U}:$ step sizes; $r:$ target tubal-rank; $\varepsilon:$ tolerance level.
\State Set 
$\mathcal{T}_0 = 0 \in \mathbb{K}^{n_1\times n_2\times n_3}$
\While{$e_k>\varepsilon$} \algorithmiccomment{\textcolor{officegreen}{$e_k$ is defined in \eqref{eqn:relative error}}}
\State $[\mathcal{R}_{k+1}]_{:,J^{\complement},:} = [\mathcal{T}_k]_{I,J^{\complement},:} + \eta_{R} [\mathcal{P}_{\Omega_\mathcal{R}}([\mathcal{T}]_{\Omega_{\mathcal{R}}\cup \Omega_{\mathcal{C}}} -\mathcal{T}_k)]_{I,J^{\complement},:}$
\State $[\mathcal{C}_{k+1}]_{I^{\complement},:,:} = [\mathcal{T}_k]_{I^{\complement},J,:} + \eta_{C} [\mathcal{P}_{\Omega_\mathcal{C}}([\mathcal{T}]_{\Omega_{\mathcal{R}}\cup \Omega_{\mathcal{C}}} -\mathcal{T}_k)]_{I^{\complement}, J, :}$
\State $\mathcal{U}_{k+1} =  \mathcal{H}_{r}([\mathcal{T}_k]_{I,J,:} + \eta_{U}[\mathcal{P}_{\Omega_{\mathcal{R}}\cup \Omega_{\mathcal{C}}}([\mathcal{T}]_{\Omega_{\mathcal{R}}\cup \Omega_{\mathcal{C}}}-\mathcal{T}_k)]_{I,J,:})$
\State $[\mathcal{R}_{k+1}]_{:,J,:} = \mathcal{U}_{k+1}$ 
\quad and \quad  $[\mathcal{C}_{k+1}]_{I,:,:} = \mathcal{U}_{k+1}$
\State  Update $\mathcal{T}_{k+1}$
\Comment{\textcolor{officegreen}{More details see \eqref{IcJ}, \eqref{IJc}, \eqref{IJ}}}
\State $k = k + 1$
\EndWhile
\State \textbf{Output:} $\mathcal{C}_{k+1}$, $\mathcal{U}_{k+1}$ and $\mathcal{R}_{k+1}$
\end{algorithmic}

