\label{lmm:key} 
Suppose $A$ is a block diagonal matrix, i.e., $A= 
\begin{bmatrix}
A_{1}  & && \\
& A_{2}  &&\\
& &\ddots & \\
& & &A_{n_3}
\end{bmatrix}$,   
  where  $A_i\in\mathbb{K}^{n_1\times r_i}$ and $A_{i}^{\top}A_{i} = \mathbb{I}_{r_i}$ ($r_i\times r_i$ identity matrix). Set $\vec{r}=(r_1,\cdots,r_{n_3})$. Let $I$ be a random subset of $[n_1]$.  Then for any $\delta\in [0,1)$, the $\|\vec{r}\|_1$-th   singular value of the matrix
\[N =:
\begin{bmatrix}
[\mathcal{S}_{I}]_{:,:,1}
 & & & \\
& [\mathcal{S}_{I}]_{:,:,1}& & \\
& & \ddots & \\
& & & [\mathcal{S}_{I}]_{:,:,1}
\end{bmatrix}
\begin{bmatrix}
A_{1}  & && \\
& A_{2}  &&\\
& &\ddots & \\
& & &A_{n_3}
\end{bmatrix}
\]
will be no less  than $\sqrt{\frac{(1-\delta)|I|}{n_1}}$ with probability at least 
\[1-\|\vec{r}\|_1e^{-(\delta+(1-\delta)\log(1-\delta))\frac{|I|}  {n_{1}\max_{i\in[n_1n_3]}{\|[A]_{i,:}\|_{{\mathrm{F}}}^2}}}.\]
\begin{proof}
Firstly, it is easy to check that 
\begin{align*}
N=\left[\mathbb{I}_{n_3}\otimes[\mathcal{S}_{I}]_{:,:,1}\right]\cdot A =\sum\limits_{i \in I} \sum_{j=1}^{n_3} \mathbf{e}_{(j-1) n_1+i}\cdot [A]_{(j-1) n_1+i,:},
\end{align*}
where $\mathbf{e}_{(j-1) n_1+i}\in\mathbb{K}^{n_{1}n_3}$ is the standard column basis vector. 
Consider $\|\vec{r}\|_1\times \|\vec{r}\|_1$ Gram matrix
\begin{align*}
Y:= N^{\top}\cdot N
=&\sum_{i\in I}\sum_{j=1}^{n_3} (\mathbf{e}_{(j-1) n_1+i}\cdot [A]_{(j-1) n_1+i,:})^{\top}\cdot \mathbf{e}_{(j-1) n_1+i}\cdot [A]_{(j-1) n_1+i,:}\\
=&\sum_{i\in I}\sum_{j=1}^{n_3} [A]_{(j-1) n_1+i,:}^{\top} [A]_{(j-1) n_1+i,:}=:\sum_{i\in I} X_i,
\end{align*} 
where $X_i=\sum\limits_{j=1}^{n_3} [A]_{(j-1) n_1+i,:}^{\top} [A]_{(j-1) n_1+i,:}$. It is easy to see that $Y$ is a random matrix due to randomness inherited from the random set $I$. It is easy to see that each $X_i$ is a positive semidefinite matrix of size $\|\vec{r}\|_1\times \|\vec{r}\|_1$. Thus, the random matrix $Y$ in fact is a sum of $|I|$
random matrices 
sampled without replacement from the   set $\left\{X_1, X_2, \cdots X_{n_1}\right\}$ of positive semi-definite matrices. 
Notice that 
\begin{align*}
\lambda_{\max}\left(X_i\right) 
    &= \lambda_{\max}\left( \sum_{j=1}^{n_3} (\mathbf{e}_{(j-1) n_1+i}\cdot [A]_{(j-1) n_1+i,:})^{\top}\cdot \mathbf{e}_{(j-1) n_1+i}\cdot [A]_{(j-1) n_1+i,:}\right)\\
&=\left|\sigma_{\max}\left(\sum_{j=1}^{n_3} \mathbf{e}_{(j-1) n_1+i}\cdot [A]_{(j-1) n_1+i,:}\right)\right|^{2} 

    \leq \max_{i}\|[A]_{i,:}\|_{{\mathrm{F}}}^{2}.
\end{align*}
By the orthogonal property of matrix $A$, it is easy to see that $\mathbb{E}\left(X_i\right)=\frac{1}{n_1}\mathbb{I}_{\|\vec{r}\|_1}$ and thus $\mathbb{E}(Y)=\frac{|I|}{n_1}$.  Thus, by the fact that $\lambda_{\min}(Y) = \sigma_{\min}^2(N)$ and by the matrix Chernoff inequality, we have
\[
\mathbb{P}\left(\sigma_{\min}(N) \leq \sqrt{\frac{(1-\delta) |I|}{n_1}}\right) \leq
\|\vec{r}\|_1e^{-(\delta+(1-\delta)\log(1-\delta))\frac{|I|}  {n_{1}\max_{i\in[n_1n_3]}{\|[A]_{i,:}\|_{{\mathrm{F}}}^2}}}, \forall \delta \in [0,1).
\]
\end{proof}

