\end{algorithmic}

\label{lmm:c_incoherence1} 
Let $\mathcal{T} \in \mathbb{K}^{n_1 \times n_2 \times n_3}$ satisfy the tensor $\mu_0$-incoherence condition. Suppose that $\mathcal{T}$ has a compact t-SVD $\mathcal{T}=\mathcal{W}\ast\Sigma \ast\mathcal{V}^{\top}$ and a condition number $\kappa$.  Consider the subtensors $\mathcal{C}=[\mathcal{T}]_{:,J,:}$ and $\mathcal{R}=[\mathcal{T}]_{I,:,:}$, each maintaining the same tubal-rank as  $\mathcal{T}$. Their compact t-SVDs are represented as \[\mathcal{C}=\mathcal{W}_{\mathcal{C}}*\Sigma_{\mathcal{C}}*\mathcal{V}_{\mathcal{C}}^{\top} ~\text{and}~ \mathcal{R}=\mathcal{W}_{\mathcal{R}}*\Sigma_{\mathcal{R}}*\mathcal{V}_{\mathcal{R}}^{\top},\] then the following results hold:
\[\mu_{\mathcal{C}}\leq \kappa^2 \left\|[\mathcal{V}]_{J,:,:}^{\dagger}\right\|^2\frac{|J|}{n_2}\mu_0,~ \text{ and } ~\mu_{\mathcal{R}}\leq \kappa^2 \left\|[\mathcal{W}]_{I,:,:}^{\dagger}\right\|^2\frac{|I|}{n_1}\mu_0.\]

According to   \Cref{lmm:key} by setting $\delta=0.815$ and $\beta_1=\beta_2=\beta$, we can easily get that 
\begin{align*}
    \mathbb{P}\left(\|[\mathcal{V}]_{J,:,:}^\dagger\|\leq \sqrt{\frac{25n_2}{4|J|}},\textnormal{rank}_m(\mathcal{C})=\textnormal{rank}_m(\mathcal{T})\right)\geq& 1-\frac{1}{n_2^\beta},\\
     \mathbb{P}\left(\|[\mathcal{W}]_{I,:,:}^\dagger\|\leq \sqrt{\frac{25n_1}{4|I|}},\textnormal{rank}_m(\mathcal{R})=\textnormal{rank}_m(\mathcal{T})\right)\geq& 1-\frac{1}{n_1^\beta}.
\end{align*}
 Therefore, 
 \begin{align}
    \mathbb{P}\left(\mu_{\mathcal{C}}\leq \frac{25}{4}\kappa^2 \mu_0,\textnormal{rank}_m(\mathcal{C})=\textnormal{rank}_m(\mathcal{T})\right)\geq& 1-\frac{1}{n_2^\beta}, \label{eqn:muC}\\
     \mathbb{P}\left(\mu_{\mathcal{R}}\leq \frac{25}{4}\kappa^2 \mu_0,\textnormal{rank}_m(\mathcal{R})=\textnormal{rank}_m(\mathcal{T})\right)\geq& 1-\frac{1}{n_1^\beta}\label{eqn:muR}.
\end{align}
Combining \eqref{eqn:muC} and \eqref{eqn:muR}, we can conclude that \[\textnormal{rank}_m(\mathcal{R})=\textnormal{rank}_m(\mathcal{C})=\textnormal{rank}_m(\mathcal{T}), 
\mu_{\mathcal{C}}\leq \frac{25}{4}\kappa^2 \mu_0 \text{ and } 
 \mu_{\mathcal{R}}\leq \frac{25}{4}\kappa^2 \mu_0\] 
 with probability at least $1-\frac{1}{n_1^{\beta}}-\frac{1}{n_2^{\beta}}$ 
provided that  \[|I|\geq 2\beta \mu_0 \|\vec{r}\|_{\infty} \log \left(n_1\|\vec{r}\|_{1}\right) \text{ and }   |J|\geq 2\beta \mu_0 \|\vec{r}\|_{\infty} \log \left(n_2\|\vec{r}\|_{1}\right).\]
